using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.SceneManagement;using DeliveryRider;using Newtonsoft.Json;
public static class SidewalkFinalAudit {
public static string Run(){var scene=SceneManager.GetActiveScene();var roots=scene.GetRootGameObjects();var map=roots.Single(g=>g.name=="MyeongjiMap");var floor=map.transform.Find("Ground").GetComponentInChildren<MeshCollider>();var net=roots.Single(g=>g.name=="Pedestrians").GetComponent<PedestrianNetwork>();Physics.SyncTransforms();var materials=floor.GetComponent<Renderer>().sharedMaterials;var ends=new List<int>();int count=0;for(int i=0;i<floor.sharedMesh.subMeshCount;i++){count+=(int)floor.sharedMesh.GetIndexCount(i)/3;ends.Add(count);}var failed=new List<object>();var edges=new List<string>();var all=new List<object>();int samples=0;
for(int i=0;i<net.PathCount;i++){var path=net.Path(i);var fail=new List<string>();foreach(var next in path.next)if(next<0||next>=net.PathCount||Vector3.Distance(path.points.Last(),net.Path(next).points.First())>.1f)edges.Add(i+"->"+next);var points=new List<Vector3>();for(int j=1;j<path.points.Length;j++){int n=Mathf.Max(1,Mathf.CeilToInt(Vector3.Distance(path.points[j-1],path.points[j])/.5f));for(int k=0;k<n;k++)points.Add(Vector3.Lerp(path.points[j-1],path.points[j],k/(float)n));}points.Add(path.points.Last());foreach(var p in points){samples++;var hits=Physics.OverlapCapsule(p+Vector3.up*.8f,p+Vector3.up*1.5f,path.halfWidth,~0,QueryTriggerInteraction.Ignore).Where(c=>c!=floor&&c.attachedRigidbody==null).ToArray();if(hits.Length>0&&fail.Count<4)fail.Add("blocked "+p+" "+string.Join(",",hits.Select(c=>c.name)));if(path.halfWidth<.99f)continue;for(int k=0;k<8;k++){var q=p+new Vector3(Mathf.Cos(k*Mathf.PI/4),0,Mathf.Sin(k*Mathf.PI/4))*path.halfWidth;string material="none";if(floor.Raycast(new Ray(q+Vector3.up*20,Vector3.down),out var hit,40)){int sub=ends.FindIndex(e=>hit.triangleIndex<e);if(sub>=0)material=materials[sub].name;}if(!material.Contains("Pavement")&&fail.Count<4)fail.Add("surface "+q+" "+material);}}
var row=new{id=i,width=path.halfWidth,path.connector,path.reverse,path.next,start=path.points.First().ToString("F3"),end=path.points.Last().ToString("F3"),fail};all.Add(row);if(fail.Count>0)failed.Add(row);}
var result=new{ground=floor.sharedMesh.name,dirty=scene.isDirty,paths=net.PathCount,samples,edges,failed};File.WriteAllText("Docs/MapLayout/Myeongji/sidewalk_final_audit.json",JsonConvert.SerializeObject(new{result,all},Formatting.Indented));return JsonConvert.SerializeObject(result);}}
